CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA private; CREATE SCHEMA storage;
GRANT USAGE ON SCHEMA auth,public,private TO authenticated;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE public.organisations(id uuid PRIMARY KEY);
CREATE TABLE public.profiles(id uuid PRIMARY KEY,org_id uuid REFERENCES public.organisations(id),full_name text,email text,job_title text,is_exec boolean DEFAULT false,is_admin boolean DEFAULT false,active boolean DEFAULT true);
CREATE TABLE public.units(id uuid PRIMARY KEY,org_id uuid,name text,active boolean DEFAULT true);
CREATE TABLE public.unit_memberships(profile_id uuid,org_id uuid,unit_id uuid,role text);
CREATE TABLE public.sub_teams(id uuid PRIMARY KEY,name text);
CREATE TABLE public.projects(id uuid PRIMARY KEY,org_id uuid,kind text,lead_unit_id uuid,name text,purpose text,starts_on date,ends_on date,status text,created_by uuid);
CREATE TABLE public.project_units(project_id uuid,unit_id uuid,role text);
CREATE TABLE public.capabilities(profile_id uuid,org_id uuid,capability text);
CREATE TABLE public.activity_events(org_id uuid,actor_id uuid,verb text,object_type text,object_id uuid,meta jsonb);
CREATE TABLE public.work_items(id uuid PRIMARY KEY,org_id uuid,assigned_by uuid);
CREATE TABLE public.work_activity_records(id uuid PRIMARY KEY,next_action text);
CREATE TABLE public.rooms(id uuid PRIMARY KEY,org_id uuid,kind text,unit_id uuid,sub_team_id uuid,project_id uuid,created_at timestamptz DEFAULT now());
CREATE TABLE public.room_messages(id uuid PRIMARY KEY,room_id uuid REFERENCES public.rooms(id),org_id uuid,author_id uuid,body text,reply_to_id uuid REFERENCES public.room_messages(id),created_at timestamptz DEFAULT now());
CREATE TABLE public.room_reads(room_id uuid,profile_id uuid,last_read_at timestamptz);
CREATE TABLE public.room_message_refs(id uuid PRIMARY KEY,message_id uuid);
CREATE TABLE public.room_mentions(message_id uuid,profile_id uuid);
CREATE TABLE public.announcements(id uuid,org_id uuid,author_id uuid);
CREATE FUNCTION public.app_org_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT org_id FROM public.profiles WHERE id=auth.uid() $$;
CREATE FUNCTION public.app_privileged_aal_allowed() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT true $$;
CREATE FUNCTION public.app_stage2_universal_aal_allowed() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT true $$;
CREATE FUNCTION public.app_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT coalesce((SELECT is_admin FROM public.profiles WHERE id=auth.uid()),false) $$;
CREATE FUNCTION public.app_is_exec() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT coalesce((SELECT is_exec FROM public.profiles WHERE id=auth.uid()),false) $$;
CREATE FUNCTION public.app_my_units() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT unit_id FROM public.unit_memberships WHERE profile_id=auth.uid() $$;
CREATE FUNCTION public.app_managed_units() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT unit_id FROM public.unit_memberships WHERE profile_id=auth.uid() AND role='manager' $$;
CREATE FUNCTION public.app_visible_projects() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT p.id FROM public.projects p WHERE p.org_id=public.app_org_id() AND (public.app_is_admin() OR p.lead_unit_id IN(SELECT public.app_my_units())) $$;
CREATE FUNCTION public.app_can_access_room(p_room_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM public.rooms r WHERE r.id=p_room_id AND r.org_id=public.app_org_id() AND (public.app_is_admin() OR r.unit_id IN(SELECT public.app_my_units()))) $$;
CREATE FUNCTION public.app_can_see_item(uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT false $$;
CREATE FUNCTION public.app_can_review_item(uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT false $$;
CREATE FUNCTION public.app_can_manage_delivery_project(uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT false $$;
CREATE FUNCTION public.app_can_read_announcement(uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT false $$;
CREATE FUNCTION public.app_can_publish_announcements() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT false $$;
ALTER TABLE public.room_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY room_messages_read ON public.room_messages FOR SELECT TO authenticated USING(org_id=public.app_org_id() AND public.app_can_access_room(room_id));
ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY;
CREATE POLICY rooms_read ON public.rooms FOR SELECT TO authenticated USING(public.app_can_access_room(id));
CREATE FUNCTION public.reject_room_message_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Room messages are append-only.' USING ERRCODE='42501'; END; $$;
CREATE TRIGGER room_messages_immutable BEFORE UPDATE OR DELETE ON public.room_messages FOR EACH ROW EXECUTE FUNCTION public.reject_room_message_mutation();
GRANT SELECT ON public.profiles,public.units,public.sub_teams,public.unit_memberships,public.rooms,public.room_messages,public.room_reads,public.room_mentions,public.room_message_refs,public.projects TO authenticated;
